-- Spoonbill bounded browser retention: explicit PostgreSQL forward upgrade.
-- Generated by scripts/export-browser-auth-schema.mjs; do not edit directly.
-- Drain every old serving/writing binary first; do not run mixed versions.
-- Apply after V4 and V5 in one transaction before retention-aware nodes start.
-- Existing slot/view activity starts at migration time, delaying initial reclamation.
-- The provider creates per-scope issuance/floor metadata while holding its realm admission lock.
-- Reclamation is incompatible with rollback to binaries that ignore these permanent fences.
-- Rollbacks must remain retention-aware and preserve metadata and host transaction guarantees.
-- NEVER delete a reclamation-floor record, reset its counters/floors, or drop this metadata table.

CREATE TABLE IF NOT EXISTS spoonbill_browser_retention (
      realm VARCHAR(96) NOT NULL, namespace VARCHAR(96) NOT NULL, id_prefix BIGINT NOT NULL, credential_key BYTEA NOT NULL,
      id_counter BIGINT NOT NULL DEFAULT 0 CHECK(id_counter>=0 AND id_counter<=4611686018427387903),
      binding_floor BIGINT NOT NULL DEFAULT 0 CHECK(binding_floor>=0),
      view_floor BIGINT NOT NULL DEFAULT 1 CHECK(view_floor>0), PRIMARY KEY(realm,namespace));

ALTER TABLE spoonbill_browser_slot ADD COLUMN IF NOT EXISTS last_seen
      TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP;

ALTER TABLE spoonbill_browser_view ADD COLUMN IF NOT EXISTS last_seen
      TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP;
